CREATE OR REPLACE FUNCTION public.claim_site_ai(_id uuid) RETURNS SETOF public.site_ai_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.site_ai_requests;BEGIN SELECT * INTO r FROM public.site_ai_requests WHERE id=_id FOR UPDATE;IF r.id IS NULL OR r.status NOT IN ('queued','waiting','running') OR r.next_attempt_at>now() THEN RETURN;END IF;IF r.status='running' AND r.lease_until>now() THEN RETURN;END IF;IF r.status='running' AND r.reserved>0 THEN PERFORM public.settle_site_ai(r.id,r.lease_version,'uncertain','Provider outcome uncertain after interruption; partial text saved. No duplicate generation sent.',r.reserved,0);RETURN;END IF;IF r.deadline<now() OR r.attempt_serial>=300 OR NOT EXISTS(SELECT 1 FROM public.project_ai_settings WHERE project_id=r.project_id AND cloudflare_enabled) OR NOT EXISTS(SELECT 1 FROM public.ai_pool_settings WHERE id='global' AND cloudflare_pool_enabled) THEN UPDATE public.site_ai_requests SET status='failed',error='AI is off, paused, or request expired.',updated_at=now() WHERE id=_id;RETURN;END IF;RETURN QUERY UPDATE public.site_ai_requests SET status='running',lease_version=lease_version+1,lease_until=now()+interval '3 minutes',usage_day=(now() AT TIME ZONE 'UTC')::date,key_position=CASE WHEN usage_day<>(now() AT TIME ZONE 'UTC')::date THEN 0 ELSE key_position END,provider_id=CASE WHEN usage_day<>(now() AT TIME ZONE 'UTC')::date THEN NULL ELSE provider_id END,key_attempt=CASE WHEN usage_day<>(now() AT TIME ZONE 'UTC')::date THEN 0 ELSE key_attempt END,updated_at=now() WHERE id=_id RETURNING *;END $$;
CREATE OR REPLACE FUNCTION public.reserve_site_ai(_id uuid,_version integer,_provider text,_position integer,_cost integer,_observed integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.site_ai_requests;u integer;v integer;e boolean;BEGIN SELECT * INTO r FROM public.site_ai_requests WHERE id=_id AND lease_version=_version AND status='running' AND lease_until>now() FOR UPDATE;IF r.id IS NULL OR _cost<0 OR _cost>9500 OR r.reserved>0 THEN RETURN false;END IF;IF NOT EXISTS(SELECT 1 FROM public.project_ai_settings WHERE project_id=r.project_id AND cloudflare_enabled) OR NOT EXISTS(SELECT 1 FROM public.ai_pool_settings WHERE id='global' AND cloudflare_pool_enabled) THEN RETURN false;END IF;PERFORM pg_advisory_xact_lock(hashtextextended(_provider||r.usage_day::text,0));IF EXISTS(SELECT 1 FROM public.site_ai_key_state WHERE provider_id=_provider AND day=r.usage_day AND cooldown_until>now()) THEN RETURN false;END IF;SELECT neurons_used,exhausted INTO u,e FROM public.cloudflare_neuron_usage WHERE provider_id=_provider AND day=r.usage_day;SELECT coalesce(sum(reserved),0) INTO v FROM public.site_ai_requests WHERE provider_id=_provider AND usage_day=r.usage_day AND reserved>0 AND id<>_id;u:=greatest(coalesce(u,0),coalesce(_observed,0));IF coalesce(e,false) OR u+v>=9000 OR u+v+_cost>9500 THEN RETURN false;END IF;UPDATE public.site_ai_requests SET provider_id=_provider,key_position=_position,key_attempt=CASE WHEN provider_id=_provider THEN key_attempt+1 ELSE 1 END,attempt_serial=attempt_serial+1,reserved=_cost,updated_at=now() WHERE id=_id;RETURN true;END $$;
CREATE OR REPLACE FUNCTION public.settle_site_ai(_id uuid,_version integer,_outcome text,_error text,_neurons integer,_delay integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.site_ai_requests;BEGIN SELECT * INTO r FROM public.site_ai_requests WHERE id=_id AND lease_version=_version AND status='running' FOR UPDATE;IF r.id IS NULL THEN RETURN false;END IF;IF r.provider_id IS NOT NULL AND r.reserved>0 THEN PERFORM pg_advisory_xact_lock(hashtextextended(r.provider_id||r.usage_day::text,0));INSERT INTO public.neuron_call_ledger(user_id,project_id,request_key,section,provider_id,key_number,model,neurons,source,action,status,created_at) VALUES(r.user_id,r.project_id,'site:'||r.id||':'||r.attempt_serial,'chat',r.provider_id,r.key_position,r.model,greatest(0,_neurons),'estimate','site_chat',_outcome,CASE WHEN r.usage_day<>(now() AT TIME ZONE 'UTC')::date THEN r.usage_day::timestamp AT TIME ZONE 'UTC' ELSE now() END);IF _outcome='quota' THEN INSERT INTO public.cloudflare_neuron_usage(provider_id,day,neurons_used,exhausted,updated_at) VALUES(r.provider_id,r.usage_day,0,true,now()) ON CONFLICT(provider_id,day) DO UPDATE SET exhausted=true,updated_at=now();END IF;IF _outcome IN ('retry','next') THEN INSERT INTO public.site_ai_key_state(provider_id,day,cooldown_until) VALUES(r.provider_id,r.usage_day,now()+make_interval(secs=>CASE WHEN _outcome='next' THEN greatest(300,_delay) ELSE greatest(1,_delay) END)) ON CONFLICT(provider_id,day) DO UPDATE SET cooldown_until=EXCLUDED.cooldown_until;END IF;END IF;UPDATE public.site_ai_requests SET status=CASE WHEN _outcome='complete' THEN 'completed' WHEN _outcome IN ('failed','uncertain','denied') THEN 'failed' ELSE 'waiting' END,error=nullif(_error,''),reserved=0,next_attempt_at=now()+make_interval(secs=>greatest(1,_delay)),lease_until=NULL,key_position=CASE WHEN _outcome IN ('quota','next') THEN key_position+1 ELSE key_position END,provider_id=CASE WHEN _outcome IN ('quota','next') THEN NULL ELSE provider_id END,key_attempt=CASE WHEN _outcome IN ('quota','next') THEN 0 ELSE key_attempt END,updated_at=now() WHERE id=_id;RETURN true;END $$;
CREATE OR REPLACE FUNCTION public.dispatch_site_ai(_id uuid) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,net AS $$ DECLARE rid bigint;tok text;BEGIN IF NOT EXISTS(SELECT 1 FROM public.site_ai_requests WHERE id=_id AND (status IN ('queued','waiting') AND next_attempt_at<=now() OR status='running' AND lease_until<now())) THEN RETURN NULL;END IF;SELECT token INTO tok FROM public.job_resume_config WHERE id='default';IF tok IS NULL THEN RAISE EXCEPTION 'Recovery configuration missing';END IF;SELECT net.http_post(url:='https://project--4cd30b31-2a37-4c66-9cee-ab3d574ad805.lovable.app/api/public/sites/ai/resume',headers:=jsonb_build_object('Content-Type','application/json','x-resume-token',tok),body:=jsonb_build_object('requestId',_id),timeout_milliseconds:=600000) INTO rid;RETURN rid;END $$;